export function initPluginApiDispatcher(): void {
  // 同步分发（ipcRenderer.sendSync / ipcRenderer.send → ipcMain.on）
  ipcMain.on('plugin.api', (event, apiName: string, args: unknown) => {
    const handler = pluginApiServices[apiName]
    if (!handler) {
      console.warn(`[plugin.api:dispatch] API "${apiName}" not found`)
      event.returnValue = new Error(`API "${apiName}" not found`)
      return
    }
    try {
      handler(event, args)
    } catch (e) {
      // 同步 handler 异常兜底：确保 event.returnValue 始终被设置
      if (event.returnValue === undefined || event.returnValue === null) {
        event.returnValue = e instanceof Error ? e : new Error(String(e))
      }
      console.error(`[plugin.api:sync] handler "${apiName}" threw:`, e)
    }
  })

  // 异步分发（ipcRenderer.invoke → ipcMain.handle）
  ipcMain.handle('plugin.api', async (event, apiName: string, args: unknown) => {
    const handler = pluginApiServices[apiName]
    if (!handler) {
      console.warn(`[plugin.api:dispatch] API "${apiName}" not found`)
      throw new Error(`API "${apiName}" not found`)
    }
    try {
      return await handler(event, args)
    } catch (e) {
      console.error(`[plugin.api:async] handler "${apiName}" threw:`, e)
      throw e
    }
  })

private getPluginPrefix(event: IpcMainEvent | IpcMainInvokeEvent): string | null {
  // 1. 检查是否来自插件主 BrowserView
  const pluginInfo = this.pluginManager?.getPluginInfoByWebContents(event.sender)
  if (pluginInfo) {
    return getPluginDataPrefix(pluginInfo.name)
  }

  // 2. 检查是否来自插件创建的子窗口（BrowserWindow）
  const pluginName = pluginWindowManager.getPluginNameByWebContentsId(event.sender.id)
  if (pluginName) {
    return getPluginDataPrefix(pluginName)
  }

  const partition = (event.sender.session as any)?.partition
  if (typeof partition === 'string' && partition.startsWith('persist:')) {
    const partitionPluginName = partition.slice('persist:'.length)
    if (partitionPluginName) {
      return getPluginDataPrefix(partitionPluginName)
    }
  }

  return null

ipcMain.on('db:get', (event, id) => {
  const prefix = this.getPluginPrefix(event)
  if (prefix) {
    id = prefix + id
  }
  const doc = lmdbInstance.get(id)
  // 如果是插件调用，需要去除返回文档的前缀
  if (doc && prefix && doc._id.startsWith(prefix)) {
    doc._id = doc._id.slice(prefix.length)
  }
  event.returnValue = doc

ipcMain.on('db:all-docs', (event, key) => {
  const prefix = this.getPluginPrefix(event)
  if (prefix) {
    if (Array.isArray(key)) {
      key = key.map((k) => prefix + k)
    } else if (typeof key === 'string') {
      key = prefix + key
    } else {
      // 如果未指定 key，则查询该插件下的所有文档
      key = prefix
    }
  }
  const docs = lmdbInstance.allDocs(key)
  // 如果是插件调用，需要去除返回文档的前缀
  if (prefix && Array.isArray(docs)) {
    docs.forEach((doc) => {
      if (doc._id.startsWith(prefix)) {
        doc._id = doc._id.slice(prefix.length)
      }
    })
  }
  event.returnValue = docs

